window.getChapterBySlug = function(slug) {
  return (window.allChapters || []).find(function(ch) { return ch.slug === slug; });
};

window.getChaptersBySubject = function(subject) {
  if (!subject || subject === 'All') return window.allChapters || [];
  return (window.allChapters || []).filter(function(ch) {
    return ch.subject.toLowerCase() === subject.toLowerCase();
  });
};
